// /tickets/<event-code>/ hop to Eventbrite checkout (SEO/GEO pass, 13th October 2026).
//
// The static _redirects rule could only send a fixed ?aff=BoomWeb, so incoming
// utm_* tags from ads, emails and listings were dropped before Eventbrite.
// _redirects now rewrites each known /tickets/<code>/ URL to this function,
// which keeps aff=BoomWeb and carries every utm_* parameter through.
// The code-to-Eventbrite map is regenerated by v2/build/build.py on each build.
import TICKETS from './ticket-map.mjs';

const SITE = 'https://www.boomevents.co.uk';

export function ticketLocation(path, query = {}) {
  const parts = String(path || '').split('/').filter(Boolean);
  const code = (parts[parts.length - 1] || '').toLowerCase();
  const id = TICKETS[code];
  if (!id) return `${SITE}/whats-on/`;
  const url = new URL(`https://www.eventbrite.co.uk/e/${id}`);
  url.searchParams.set('aff', 'BoomWeb');
  for (const [key, value] of Object.entries(query || {})) {
    if (/^utm_[a-z0-9_]+$/i.test(key) && value) url.searchParams.set(key.toLowerCase(), String(value).slice(0, 200));
  }
  return url.toString();
}

export const handler = async (event) => ({
  statusCode: 302,
  headers: { location: ticketLocation(event.path, event.queryStringParameters), 'cache-control': 'no-store' },
  body: '',
});
